/**
 * Coldcard Vulnerability Investigation Dashboard
 */

document.addEventListener('DOMContentLoaded', () => {
    initDashboard();
});

async function initDashboard() {
    try {
        // Fetch metrics data generated by the Python pipeline
        const response = await fetch('data/metrics.json');
        if (!response.ok) {
            throw new Error(`Failed to load metrics data: ${response.status}`);
        }
        
        const data = await response.json();
        
        updateStatCards(data.summary);
        renderTimelineChart(data.timeline);
        populateAttackerTable(data.clusters);
        
    } catch (error) {
        console.error('Error initializing dashboard:', error);
        document.getElementById('stats-container').innerHTML = `
            <div style="grid-column: 1 / -1; color: #b91c1c; padding: 1rem; background: #fef2f2; border: 1px solid #f87171; border-radius: 0.5rem;">
                Failed to load data. The data pipeline may not have run yet.
            </div>
        `;
    }
}

function updateStatCards(summary) {
    if (!summary) return;
    
    document.getElementById('stat-stolen').textContent = `${summary.total_stolen_btc} BTC`;
    document.getElementById('stat-utxos').textContent = summary.swept_utxos_count.toLocaleString();
    document.getElementById('stat-rescued').textContent = `${summary.estimated_rescued_btc} BTC`;
}

function renderTimelineChart(timelineData) {
    if (!timelineData || timelineData.length === 0) return;
    
    const ctx = document.getElementById('timelineChart').getContext('2d');
    
    new Chart(ctx, {
        type: 'line',
        data: {
            labels: timelineData.map(d => d.date),
            datasets: [{
                label: 'BTC Stolen (Daily)',
                data: timelineData.map(d => d.stolen_amount),
                borderColor: '#ef4444',
                backgroundColor: 'rgba(239, 68, 68, 0.1)',
                borderWidth: 2,
                fill: true,
                tension: 0.1
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    type: 'time',
                    time: {
                        unit: 'day',
                        tooltipFormat: 'MMM d, yyyy'
                    },
                    title: {
                        display: true,
                        text: 'Date'
                    }
                },
                y: {
                    beginAtZero: true,
                    title: {
                        display: true,
                        text: 'BTC'
                    }
                }
            },
            plugins: {
                tooltip: {
                    mode: 'index',
                    intersect: false,
                }
            }
        }
    });
}

function populateAttackerTable(clusters) {
    if (!clusters || clusters.length === 0) return;
    
    const tbody = document.querySelector('#attacker-table tbody');
    tbody.innerHTML = '';
    
    clusters.forEach(cluster => {
        const tr = document.createElement('tr');
        
        // Link to a block explorer for the address/cluster
        const addressLink = `<a href="https://mempool.space/address/${cluster.address}" target="_blank" rel="noopener noreferrer">${cluster.address}</a>`;
        
        tr.innerHTML = `
            <td style="font-family: monospace;">${addressLink}</td>
            <td>${cluster.first_seen}</td>
            <td>${cluster.total_received}</td>
            <td>${cluster.current_balance}</td>
        `;
        tbody.appendChild(tr);
    });
}
